test('WhatsApp delivery webhook resolves accepted message exactly once and cannot downgrade read', async (t) => {
    const f = await fixture();
    t.after(() => f.cleanup());
    const a = addAccount(f, 'whatsapp', 'direct', 'phone-1', { appSecret: 'secret' });
    let e = addContent(f, a.id, { format: 'template', options: { recipient: '391234', template: { name: 'test', language: { code: 'it' } } } });
    e = f.store.update(f.p, e.id, e.revision, { ...e.data, status: 'PROCESSING', publication: { state: 'PROCESSING', externalId: 'wamid.1', details: { stage: 'webhook', delivery: 'accepted' } } });
    const hooks = new Webhooks(f.studio);
    for (const status of ['read', 'delivered', 'read']) {
        const raw = Buffer.from(JSON.stringify({ entry: [{ changes: [{ value: { metadata: { phone_number_id: 'phone-1' }, statuses: [{ id: 'wamid.1', status }] } }] }] }));
        await hooks.receive(a.id, { 'x-hub-signature-256': 'sha256=' + hmac(raw, 'secret') }, raw);
    }
    const saved = f.studio.content(f.p, e.id);
    assert.equal(saved.data.status, 'PUBLISHED');
    assert.equal(saved.data.publication?.details?.delivery, 'read');
});
test('Telegram callback approval requires signed webhook, exact chat and current human membership', async (t) => {
    const f = await fixture();
    t.after(() => f.cleanup());
    const a = addAccount(f, 'telegram', 'direct', '-1001', {}, { approvalChatId: '-999', approvers: { '123': f.p.userId } });
    f.http.handler = () => response({ ok: true, result: true });
    let e = addContent(f, a.id);
    e = await f.studio.review(f.p, e.id);
    const hooks = new Webhooks(f.studio);
    const headers = { 'x-telegram-bot-api-secret-token': 'signed-test-secret' };
    const raw = (chat, update) => Buffer.from(JSON.stringify({ update_id: update, callback_query: { id: 'callback' + update, from: { id: 123 }, message: { chat: { id: chat } }, data: `ap:${e.id}:${e.revision}` } }));
    await hooks.receive(a.id, headers, raw('-other', 1));
    assert.equal(f.studio.content(f.p, e.id).data.status, 'WAITING_APPROVAL');
    await hooks.receive(a.id, headers, raw('-999', 2));
    assert.equal(f.studio.content(f.p, e.id).data.status, 'APPROVED');
    const count = f.http.calls.length;
    await hooks.receive(a.id, headers, raw('-999', 2));
    assert.equal(f.http.calls.length, count);
    assert.equal(f.store.jobs(f.p, f.brand.id).length, 0);
});
